def admission(s:readbuf, w:mutbuf, phase:u64) -> u64:
    if phase == 1:
        return request(w, 1, 1, 0, 0, 0, 2)
    if phase == 2:
        n = fact(w, 0, 8)
        if fact(w, 0, 0) != 1 or fact(w, 0, 16) != 0 or (n != 16 and n != 32 and n != 64):
