        return request(w, 2, get(w, SYMARG), 0, 0, 0, 10)
    if phase == 10:
        put(w, ITER, fact(w, 0, 32))
        return request(w, 3, get(w, ITER), 0, 0, 0, 11)
    if phase == 11:
        if fact(w, 0, 0) == 0:
