def div5(value:u64) -> u64:
    quotient = 0
    remainder = 0
    index = 64
    while index != 0:
        index = index - 1
        remainder = (remainder << 1) | ((value >> index) & 1)
        if remainder >= 5:
            remainder = remainder - 5
            quotient = quotient | (1 << index)
    return quotient

