from __future__ import annotations
from pathlib import Path
from hashlib import sha256
import json,struct,sys,time,traceback
from hepta import hia_machine_elf as public
from hepta.hia_machine_elf_native import installed_machine_elf,REQUEST
from tests.test_hia_machine_elf_native import pending_lookup

ROOT=Path.cwd();OUT=ROOT/'development-evidence/peer-port-r1/boundary-observations'
OUT.mkdir(exist_ok=False)
manifest=ROOT/'development-evidence/peer-port-r1/build/manifest.json'
native=installed_machine_elf(str(manifest))
reference=public._reference_write_elf_object
inputs=(ROOT/'examples/hia_bootstrap/machine_elf.hiaasm',manifest,
        manifest.parent/json.loads(manifest.read_text())['image_path'],
        ROOT/'hepta/hia_machine_elf_native.py',ROOT/'tools/generate_hia_machine_elf.py')
before={str(p.relative_to(ROOT)):sha256(p.read_bytes()).hexdigest() for p in inputs}
def outcome(writer,code,rows,events,label):
    try:
        raw=writer(code,rows,[])
        (OUT/(label+'.elf')).write_bytes(raw)
        return {'kind':'bytes','bytes':len(raw),'sha256':sha256(raw).hexdigest(),'events':list(events)}
    except BaseException as error:
        return {'kind':'exception','type':type(error).__qualname__,'args':list(error.args),
                'traceback':traceback.format_exc(),'events':list(events)}
def temporary_set(writer,label):
    events=[];row={}
    class Key:
        def __init__(self,owner):self.owner=owner
        def __hash__(self):return hash('name')
        def __eq__(self,other):
            if type(other) is str and other=='name':
                events.append('key-equality-clears-row')
                self.owner.clear()
                return True
            return False
        def __del__(self):
            events.append('temporary-key-released-restores-row')
            self.owner.update(name='entry',offset=0,size=1,**{'global':True})
    row[Key(row)]='entry';row['offset']=0;row['size']=1;row['global']=True
    result=outcome(writer,b'\xc3',[row],events,label)
    result['events_after_return']=list(events);result['row_after_return']={str(k):v for k,v in row.items()}
    return result
def sort_observation(writer,label):
    events=[];rows=[]
    class Number(int):
        def __eq__(self,other):
            events.append(('eq',int(self),int(other)))
            return int(self)==int(other)
        def __lt__(self,other):
            events.append(('lt',int(self),int(other)))
            return int(self)<int(other)
        def __gt__(self,other):
            events.append(('gt',int(self),int(other)))
            return int(self)>int(other)
    class Offset:
        def __init__(self,owner,n):self.owner=owner;self.n=n;self.count=0
        def __hash__(self):return hash('offset')
        def __eq__(self,other):
            if type(other) is str and other=='offset':
                self.count+=1
                # The first equality is the set/record comparison. The next
                # is the original exact-int admission; introduce a foreign
                # int subclass only at its subsequent real field observation.
                if self.count>=3:self.owner[self]=Number(self.n)
                return True
            return False
    for n in (2,0,1):
        row={'name':'f'+str(n),'size':1,'global':True}
        row[Offset(row,n)]=n;rows.append(row)
    result=outcome(writer,b'\xc3'*3,rows,events,label)
    result['events_after_return']=list(events)
    return result
observations={}
for name,fn in [('temporary_set',temporary_set),('foreign_sort',sort_observation)]:
    observations[name]={'original':fn(reference,name+'-original'),'native':fn(native.write,name+'-native')}
    observations[name]['same_outcome_and_observations']=observations[name]['original']==observations[name]['native']
session,ledger,_=pending_lookup(native)
try:
    issued=struct.unpack_from('<5Q',session.work,REQUEST);start=list(ledger)
    struct.pack_into('<Q',session.work,REQUEST+16,2)
    changed=struct.unpack_from('<5Q',session.work,REQUEST)
    caught=None
    try:session.observe()
    except BaseException as e:caught={'type':type(e).__qualname__,'args':list(e.args)}
    observations['issued_field_mutation']={'issued':issued,'changed':changed,'before':start,'after':list(ledger),'error':caught,
                                           'foreign_observation_occurred':ledger!=start}
finally:session.close()
after={str(p.relative_to(ROOT)):sha256(p.read_bytes()).hexdigest() for p in inputs}
report={'schema':'hia.machine-elf-v75.peer-boundary-observations.v1','scope':'ACTUAL_RETAINED_COMPILER_DEVELOPMENT_PRIVATE_PEER_IMAGE',
        'python':sys.version,'peer':'acffa9262f31d073f8f0a6f0201eae201039f619',
        'before':before,'after':after,'sources_preserved':before==after,'observations':observations,
        'tests_of_whole_domain':False,'default_changed':False}
(OUT/'SUMMARY.json').write_text(json.dumps(report,sort_keys=True,indent=2)+'\n')
print(json.dumps(report,sort_keys=True),flush=True)
